    public static IHtmlContent Svg(string name, string css = "size-5") =>
        new HtmlString($"""<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.75" stroke="currentColor" class="{css}" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="{Paths[name]}"/></svg>""");

    /// <summary>The app mark: a basketball.</summary>
    public static IHtmlContent Ball(string css = "size-7")
    {
        var id = "ball" + Guid.NewGuid().ToString("N")[..8];
        return new HtmlString($"""<svg viewBox="0 0 32 32" class="{css}" aria-hidden="true"><defs><clipPath id="{id}"><circle cx="16" cy="16" r="14.5"/></clipPath></defs><circle cx="16" cy="16" r="14.5" fill="#f97316"/><g clip-path="url(#{id})" fill="none" stroke="#1c0d03" stroke-width="1.8"><path d="M0 16h32M16 0v32"/><circle cx="-7.5" cy="16" r="18.1"/><circle cx="39.5" cy="16" r="18.1"/></g><circle cx="16" cy="16" r="14.5" fill="none" stroke="#1c0d03" stroke-width="1.8"/></svg>""");
    }
